local function DarkAIOTrimKey(value)
    local key = tostring(value or ""):gsub("^\239\187\191", "")
    return (key:gsub("^%s+", ""):gsub("%s+$", ""))
end
local function DarkAIOUrlEncode(value)
    return (tostring(value or ""):gsub("([^A-Za-z0-9_.~-])", function(ch)
        return string.format("%%%02X", string.byte(ch))
    end))
end
local function v72(url)
    if type(url) ~= "string" or not url:match("^https://[^/]+/") or url:find("[%s%c\"'<>]") then
        return eCurlCode.CURLE_URL_MALFORMAT or 3, ""
    end
    local success, code, body = pcall(function()
        local curl = Curl.Easy()
        curl:Setopt(eCurlOption.CURLOPT_URL, url)
        -- These options are optional for compatibility with older Cherax builds.
        local function option(name, value)
            local id = eCurlOption[name]
            if id ~= nil then pcall(function() curl:Setopt(id, value) end) end
        end
        option("CURLOPT_CONNECTTIMEOUT", 8)
        option("CURLOPT_TIMEOUT", 20)
        curl:Perform()
        while not curl:GetFinished() do Script.Yield(10) end
        return curl:GetResponse()
    end)
    if not success then return eCurlCode.CURLE_FAILED_INIT or 2, "" end
    return code, body
end

local function v73(value)
    local hwid = v61()
    local v523="https://dymqiosmomexoybyfhqk.supabase.co/functions/v1/auth";
    local key = DarkAIOTrimKey(value)
    local hid = tostring(hwid or "")
    if key == "" then return false, "KEY" end
    if hid == "" then return false, "HWID" end
    local url = v523 .. "?key=" .. DarkAIOUrlEncode(key) .. "&hwid=" .. DarkAIOUrlEncode(hid)
    local code, body = v72(url)
    if code ~= eCurlCode.CURLE_OK then return false, "NET_ERR" end
    body = tostring(body or ""):gsub("^\239\187\191", "")
    body = body:gsub("^%s+", ""):gsub("%s+$", "")
    if body == "OK" then return true
    elseif body == "HWID_MISMATCH" then return false, "HWID"
    elseif body == "EXPIRED" then return false, "EXP"
    elseif body == "BANNED" then return false, "BAN"
    elseif body == "DB_ERROR" then return false, "DB"
    elseif body == "SERVER_ERROR" or body == "SERVER_BUSY" then return false, "SERVER"
    elseif body == "MISSING_PARAMS" or body == "METHOD_NOT_ALLOWED" then return false, "REQUEST"
    elseif body == "RATE_LIMIT" then return false, "RATE"
    elseif body == "INVALID_KEY" then return false, "KEY"
    else return false, "UNKNOWN" end
end

